// The same change through generated code: db-conformance's `Item` (generated by ce-wire-gen --records from the Rust
// struct) with `bin` removed, as regenerating after the Rust change would write it. The caller breaks the same way.
import type { Collection, Db, Query, RecordMeta } from '../src/node.js';

export interface Item { id: string; name: string; qty: number }
export type ItemNew = Item;
export declare const ItemMeta: RecordMeta;
export interface ItemCollection extends Collection<Item, ItemNew> {}
export declare function items(db: Db): ItemCollection;

export async function caller(db: Db): Promise<Query<Item>> {
  const c = items(db);
  await c.insert({ id: 'k', name: 'x', bin: 'A4', qty: 1 });
  return c.byBin('A4');
}
